mapper.select:
select count(CATEGORY_NAME)
from TBL_CATEGORY
where CATEGORY_NAME = #{categoryName} and IS_DELETED = 0 and USER_ID= #{userId}

mapper.update:
update TBL_BUDGET
set BUDGET_AMOUNT = #{budgetAmount}
where BUDGET_ID = #{budgetId};

mapper.select:
select USER_ID, PERIOD_ID, BUDGET_AMOUNT
from TBL_BUDGET
where BUDGET_ID = #{budgetId}

SELECT COALESCE(SUM(BUDGET_AMOUNT), 0) AS TOTAL_BUDGET
FROM TBL_BUDGET
WHERE USER_ID = #{userId} AND PERIOD_ID = #{periodId}
